static BOOL SafeRelativeArtworkPath(NSString *path){if(![path isKindOfClass:NSString.class]||path.length==0||path.isAbsolutePath)return NO;for(NSString *part in path.pathComponents)if(part.length==0||[part isEqualToString:@"."]||[part isEqualToString:@".."]||[part containsString:@"/"]||[part containsString:@"\\"])return NO;return [path.pathExtension.lowercaseString isEqualToString:@"ai"]&&[path.lastPathComponent hasSuffix:@"_LIVE.ai"];}
