static int RunCopyLiveCLI(NSString *masterRoot,NSString *source,NSString *customerRoot,NSString *relative,BOOL background){__block NSString *masterHash=nil,*liveHash=nil;__block NSError *error=nil;if(!IsInsideRoot(source,masterRoot,&error)||!RejectSymlinks(source,NO,&error)||!SafeRelativeArtworkPath(relative)||!EnsureDestinationParent(customerRoot,relative,&error)){fprintf(stderr,"copy_valid=no\n%s\n",error.localizedDescription.UTF8String);return 2;}__block BOOL copied=NO;if(background){dispatch_semaphore_t done=dispatch_semaphore_create(0);dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{copied=CopyExclusiveVerified(source,[customerRoot stringByAppendingPathComponent:relative],&masterHash,&liveHash,&error);dispatch_semaphore_signal(done);});dispatch_semaphore_wait(done,DISPATCH_TIME_FOREVER);}else copied=CopyExclusiveVerified(source,[customerRoot stringByAppendingPathComponent:relative],&masterHash,&liveHash,&error);if(!copied){fprintf(stderr,"copy_valid=no\n%s\n",error.localizedDescription.UTF8String);return 2;}printf("copy_valid=yes\nmaster_sha256=%s\nlive_sha256=%s\n",masterHash.UTF8String,liveHash.UTF8String);return 0;}
